var a=`1199-stewed-chicken`;var t=`world-1199`;var n=`BZ`;var s=`central-america-caribbean`;var r=4;var o=125;var d={en:`Stewed Chicken`,ua:`Тушкована курка по-белізьки`};var h={en:`Stewed Chicken is a dish from Belize prepared with chicken thigh, achiote paste, orange juice, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used. Achiote paste approximates Belizean recado rojo; other recado spices and aromas may vary.`,ua:`Тушкована курка по-белізьки, страва кухні країни Беліз, яку готують із таких продуктів: куряче стегно, паста ачіоте, апельсиновий сік, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Паста ачіоте приблизно замінює белізький рекадо рохо; спеції й аромат можуть відрізнятися.`};var c=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 60 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 60 хвилин.`,t:[`marinating`],m:60,i:[[`chicken-thigh`,900,`g`],[`achiote-paste`,65,`g`],[`orange-juice`,100,`ml`],[`garlic`,5,`clove`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,170,`g`],[`red-bell-pepper`,170,`g`],[`canola-oil`,40,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 50 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 50 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:50,i:[[`water`,550,`ml`],[`tomato`,230,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`]]}];var g={slug:a,id:t,country:`BZ`,region:s,servings:4,minutes:125,title:d,text:h,steps:c};export{n as country,g as default,t as id,o as minutes,s as region,r as servings,a as slug,c as steps,h as text,d as title};